"""Teaching content: a short lesson on 'how this board works'. Images are generated by code
so the project needs no external files."""
import numpy as np
import cv2

INK, ACCENT = (50, 50, 50), (170, 90, 30)


def _canvas(w, h):
    return np.full((h, w, 3), 255, np.uint8)


def img_pixels(w, h):
    img = _canvas(w, h)
    cols, rows = 16, 10
    cw, ch = w // cols, h // rows
    for j in range(rows):
        for i in range(cols):
            col = (int(255 * i / cols), int(255 * j / rows), int(255 * (1 - i / cols)))
            cv2.rectangle(img, (i * cw, j * ch), ((i + 1) * cw, (j + 1) * ch), col, -1)
            cv2.rectangle(img, (i * cw, j * ch), ((i + 1) * cw, (j + 1) * ch), (255, 255, 255), 1)
    return img


def img_hue(w, h):
    img = _canvas(w, h)
    bar_w, bar_h = w - 20, h // 4
    hue = np.tile(np.linspace(0, 179, bar_w).astype(np.uint8), (bar_h, 1))
    hsv = np.dstack([hue, np.full_like(hue, 255), np.full_like(hue, 255)])
    bar = cv2.cvtColor(hsv, cv2.COLOR_HSV2BGR)
    img[30:30 + bar_h, 10:10 + bar_w] = bar
    sel = bar.copy()
    keep = (hue < 10) | (hue > 170)                      # hues accepted by a "red" threshold
    sel[~keep] = (225, 225, 225)
    img[60 + bar_h:60 + 2 * bar_h, 10:10 + bar_w] = sel
    cv2.putText(img, "Hue 0..179 (all colours)", (10, 22), cv2.FONT_HERSHEY_SIMPLEX, 0.6, INK, 1, cv2.LINE_AA)
    cv2.putText(img, "After threshold: only red stays", (10, 52 + bar_h), cv2.FONT_HERSHEY_SIMPLEX, 0.6, INK, 1, cv2.LINE_AA)
    return img


def img_segmentation(w, h):
    img = _canvas(w, h)
    rng = np.random.default_rng(1)
    mask = np.zeros((h, w), np.uint8)
    cv2.circle(mask, (w // 2, h // 2), min(w, h) // 5, 255, -1)
    ys, xs = np.nonzero(mask)
    cx, cy = int(xs.mean()), int(ys.mean())                  # centroid = mean of pixel coordinates
    noise = (rng.random((h, w)) > 0.995).astype(np.uint8) * 255
    img[(mask | noise) > 0] = (60, 60, 60)
    cv2.drawMarker(img, (cx, cy), (40, 40, 220), cv2.MARKER_CROSS, 40, 3)
    cv2.putText(img, "blob + noise -> centroid (red cross)", (10, 25), cv2.FONT_HERSHEY_SIMPLEX, 0.6, INK, 1, cv2.LINE_AA)
    return img


def img_homography(w, h):
    img = _canvas(w, h)
    quad = np.array([[0.08 * w, 0.25 * h], [0.40 * w, 0.12 * h], [0.46 * w, 0.78 * h], [0.04 * w, 0.88 * h]], np.int32)
    cv2.polylines(img, [quad], True, ACCENT, 3, cv2.LINE_AA)
    rect = np.array([[0.58 * w, 0.2 * h], [0.95 * w, 0.2 * h], [0.95 * w, 0.8 * h], [0.58 * w, 0.8 * h]], np.int32)
    cv2.polylines(img, [rect], True, ACCENT, 3, cv2.LINE_AA)
    for a, b in zip(quad, rect):
        cv2.arrowedLine(img, tuple(int(v) for v in a), tuple(int(v) for v in b), (150, 150, 150), 1, cv2.LINE_AA, tipLength=0.02)
    cv2.putText(img, "camera image", (int(0.04 * w), int(0.97 * h)), cv2.FONT_HERSHEY_SIMPLEX, 0.6, INK, 1, cv2.LINE_AA)
    cv2.putText(img, "board (mm)", (int(0.64 * w), int(0.9 * h)), cv2.FONT_HERSHEY_SIMPLEX, 0.6, INK, 1, cv2.LINE_AA)
    return img


