def make_test_image(w=1600, h=1000):
    """Detailed image to demonstrate zoom (fine text and grid are only readable when zoomed)."""
    img = _canvas(w, h)
    for x in range(0, w, 50):
        cv2.line(img, (x, 0), (x, h), (225, 225, 225), 1)
    for y in range(0, h, 50):
        cv2.line(img, (0, y), (w, y), (225, 225, 225), 1)
    for k, r in enumerate(range(380, 40, -60)):
        cv2.circle(img, (w // 2, h // 2), r, (int(50 + 30 * k), int(180 - 12 * k), 200 - 15 * k), 4, cv2.LINE_AA)
    cv2.putText(img, "TEST CHART - zoom in to read the details", (40, 60), cv2.FONT_HERSHEY_SIMPLEX, 1.4, INK, 3, cv2.LINE_AA)
    cv2.putText(img, "tiny text: the quick brown fox jumps over the lazy dog", (w // 2 - 175, h // 2), cv2.FONT_HERSHEY_SIMPLEX, 0.4, INK, 1, cv2.LINE_AA)
    cv2.putText(img, "detail A", (60, h - 40), cv2.FONT_HERSHEY_SIMPLEX, 0.35, ACCENT, 1, cv2.LINE_AA)
    cv2.putText(img, "detail B", (w - 130, 120), cv2.FONT_HERSHEY_SIMPLEX, 0.35, ACCENT, 1, cv2.LINE_AA)
    return img


def make_hue_wheel(size=900):
    img = _canvas(size, size)
    yy, xx = np.mgrid[0:size, 0:size]
    dx, dy = xx - size / 2, yy - size / 2
    rad = np.hypot(dx, dy)
    hue = ((np.arctan2(dy, dx) + np.pi) / (2 * np.pi) * 179).astype(np.uint8)
    sat = np.clip(rad / (size / 2) * 255, 0, 255).astype(np.uint8)
    hsv = np.dstack([hue, sat, np.full_like(hue, 255)])
    wheel = cv2.cvtColor(hsv, cv2.COLOR_HSV2BGR)
    img[rad < size / 2 - 5] = wheel[rad < size / 2 - 5]
    cv2.putText(img, "HSV hue wheel", (20, 40), cv2.FONT_HERSHEY_SIMPLEX, 1.0, INK, 2, cv2.LINE_AA)
    return img


def builtin_images():
    return [("Test chart (zoom)", make_test_image()), ("HSV colour wheel", make_hue_wheel())]
